with flattened as (select id, service, log_ts, attr_key, attr_value from app_logs lateral view explode(context) x as attr_key, attr_value), valid as (select id, log_ts, attr_key, attr_value, substring(service, 1, 2) as service_prefix, coalesce(attr_key, 'N/A') as resolved_attr_key from flattened where log_ts > timestamp '2025-06-01 07:00:00' and attr_key is not null), scored as (select id, attr_key, resolved_attr_key, row_number() over (partition by attr_key order by log_ts, id, attr_key) as row_seq, last_value(attr_key, true) over (partition by attr_key order by log_ts, id, attr_key rows between unbounded preceding and current row) as last_known_attr_key, row_number() over (partition by attr_key order by log_ts, id, attr_key) as event_seq, first_value(attr_key, true) over (partition by attr_key order by log_ts, id, attr_key rows between unbounded preceding and current row) as first_known_attr_key, first_value(attr_key) ignore nulls over (partition by month(log_ts), attr_key order by log_ts, id, attr_key rows between unbounded preceding and current row) as first_known_attr_key_2 from valid), ranked as (select id, attr_key, last_known_attr_key, event_seq, first_known_attr_key from scored qualify row_number() over (partition by attr_key order by row_seq desc, id, attr_key) = 1), matched_keys as (select id from ranked intersect select id from app_logs where level = 'INFO'), verified as (select s.* from ranked s inner join matched_keys k on s.id = k.id), stats as (select case when event_seq >= 7 then 'PREMIUM' else 'STANDARD' end as event_seq_tier, max(event_seq) as max_event_seq, count_if(attr_key = 'region') as region_events, count(distinct id) as distinct_ids, size(collect_set(attr_key)) as num_attr_keys from verified group by event_seq_tier) select event_seq_tier, region_events, distinct_ids, num_attr_keys from stats order by event_seq_tier nulls last;
